import channels_graphql_ws
import graphene
from graphql import GraphQLError
from .models import WardAssignment, PatientVitals
from .types import VitalsType

class PatientVitalsSubscription(channels_graphql_ws.Subscription):
    vitals = graphene.Field(VitalsType)

    class Arguments:
        ward_code = graphene.String(required=True)

    @classmethod
    def subscribe(cls, root, info, ward_code):
        user = info.context.user
        if not user.is_authenticated:
            raise GraphQLError("Physician authentication required")

        if not WardAssignment.objects.filter(staff=user, ward__code=ward_code, is_active=True).exists():
            raise GraphQLError("You are not assigned to this clinical ward")

        return [f"ward_vitals_{ward_code}"]

    @classmethod
    def publish(cls, payload, info, ward_code):
        return cls(vitals=payload.get("vitals_event"))
